H.out({doc:String(doc.id),version:sketch.version, pages:doc.pages.filter(p=>/^Proto macOS/.test(p.name)).map(p=>({name:p.name,settings:p.layers.filter(l=>l.name.indexOf('/settings')>=0).map(l=>({name:l.name,id:l.id}))})),symbols:doc.getSymbols().filter(s=>/^(Switch|Kbd|AgentLimitsCard|Dialog|Button)\/Light\/Clean/.test(s.name)).map(s=>({name:s.name,w:s.frame.width,h:s.frame.height})).slice(0,85)});